def _fmt_float(v):
    """格式化为固定 1 位整数 + 12 位小数；负零规范化为 0.000000000000。"""
    if not math.isfinite(v):
        raise ValueError("出现非有限值（NaN/inf），禁止写入产物")
    s = "%.12f" % v
    if s == "-0.000000000000":
        s = "0.000000000000"
    return s


